// Normalizador: Evolution API payload → shape legacy esperado pelas 25 expressions
const input = $input.first().json;
const evoBody = input.content?.body || {};
const data = evoBody.data || {};
const message = data.message || {};
const key = data.key || {};

const conversationText =
  message.conversation ||
  message.extendedTextMessage?.text ||
  message.listResponseMessage?.title ||
  message.templateButtonReplyMessage?.selectedDisplayText ||
  message.buttonsResponseMessage?.selectedDisplayText ||
  message.imageMessage?.caption ||
  message.videoMessage?.caption ||
  '';

// Phone resolution: senderPn (sender real) tem prioridade sobre remoteJid (@lid)
const senderPn = key.senderPn || '';
const rawJid = key.remoteJid || '';
const sourceJid = senderPn || rawJid;
const phone = sourceJid.split('@')[0];

const isGroup = rawJid.endsWith('@g.us');
const isLid = rawJid.endsWith('@lid');

const normalizedBody = {
  event: evoBody.event,
  instance: evoBody.instance,
  text: {
    message: conversationText,
  },
  senderName: data.pushName || '',
  phone: phone,
  fromMe: key.fromMe || false,
  audio: message.audioMessage || null,
  image: message.imageMessage || null,
  video: message.videoMessage || null,
  document: message.documentMessage || null,
  sticker: message.stickerMessage || null,
  isGroup: isGroup,
  isLid: isLid,
  remoteJid: rawJid,
  senderPn: senderPn,
  messageId: key.id || '',
  messageType: data.messageType || '',
  timestamp: data.messageTimestamp || 0,
  data: data,
  raw: evoBody,
  chatwootMessageId: data.chatwootMessageId,
  chatwootInboxId: data.chatwootInboxId,
  chatwootConversationId: data.chatwootConversationId,
  server_url: evoBody.server_url,
  apikey: evoBody.apikey,
};

return [{
  json: {
    body: normalizedBody,
  },
}];

const persona = $('Set Persona').first().json;
const norm = $('Normalizacao').first().json;
const searchResult = $('Airtable - Search User in Leads Autobot').all();
const lead = searchResult.length > 0 ? searchResult[0].json : {};
const cliente = persona.cliente_ativo === 'TM' ? {
  nome: persona.cliente_nome_tm,
  perguntas: persona.perguntas_tm,
  email: persona.email_tm
} : {
  nome: persona.cliente_nome_tj,
  perguntas: persona.perguntas_tj,
  email: persona.email_tj
};
const historico = lead.concat_Messages || '(primeira mensagem desta conversa)';
const respostasDadas = [1,2,3,4,5,6]
  .map(n => 'resposta' + n + ': ' + (lead['resposta' + n] || '(ainda nao respondida)'))
  .join('\n');

// ESTADO DA REUNIAO — calculado de Calendly Start vs now
// FIX 2026-07-15: pre-computar horario em Lisboa + fuso do cliente (Intl.DateTimeFormat)
// para o LLM. calendlyStart e ISO UTC; passar sem converter faz o LLM interpretar mal o fuso.
let estadoReuniao = 'nao_agendada';
let detalheReuniao = '(reuniao nao agendada)';
const calendlyStart = lead['Calendly Start Date & Time'];
const clientTz = lead['Client_Timezone'] || 'Europe/Lisbon';
if (calendlyStart) {
  const startMs = new Date(calendlyStart).getTime();
  const nowMs = Date.now();
  if (!isNaN(startMs)) {
    const startDate = new Date(startMs);
    const fmt = (tz) => new Intl.DateTimeFormat('pt-PT', {
      weekday: 'long', day: 'numeric', month: 'long', year: 'numeric',
      hour: '2-digit', minute: '2-digit', hour12: false, timeZone: tz
    }).format(startDate);
    const timeLisboa = fmt('Europe/Lisbon');
    const timeClient = (clientTz && clientTz !== 'Europe/Lisbon') ? fmt(clientTz) : null;
    const horarios = timeLisboa + ' (Lisboa)' + (timeClient ? ' / ' + timeClient + ' (' + clientTz + ')' : '');
    const hoursDelta = (nowMs - startMs) / 3600000;
    if (hoursDelta < 0) {
      estadoReuniao = 'agendada_futura';
      detalheReuniao = 'Reuniao agendada para ' + horarios + ' (no futuro).';
    } else if (hoursDelta <= 24) {
      estadoReuniao = 'decorreu_recentemente';
      detalheReuniao = 'Reuniao decorreu em ' + horarios + ', ha ' + Math.round(hoursDelta) + ' horas.';
    } else {
      estadoReuniao = 'passou_ha_muito';
      const daysDelta = Math.round(hoursDelta / 24);
      detalheReuniao = 'Reuniao decorreu em ' + horarios + ', ha ' + daysDelta + ' dias.';
    }
  }
}

// ESTADO DA CONVERSA — lido de tags (multi-select Airtable)
const tagsRaw = lead.tags;
const tagsArray = Array.isArray(tagsRaw) ? tagsRaw : [];
const tagNames = tagsArray.map(t => typeof t === 'string' ? t : ((t && t.name) || ''));
const conversaFinalizada = tagNames.includes('Conversa Finalizada');
const estadoConversa = conversaFinalizada ? 'finalizada' : 'ativa';

// Mensagem nova - prioridade: audio transcrito / imagem descrita (Merge1) > buffer do
// debouncer (mensagens de texto agregadas, limpo de representacao crua de array tipo
// "['Oi']") > texto simples da Normalizacao. Nunca deixa passar array cru para o prompt.
function limparBufferDebounce(raw) {
  if (Array.isArray(raw)) return raw.filter(Boolean).join('\n');
  if (typeof raw !== 'string') return '';
  const trimmed = raw.trim();
  if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
    try {
      const arr = JSON.parse(trimmed.replace(/'/g, '"'));
      if (Array.isArray(arr)) return arr.filter(Boolean).join('\n');
    } catch (e) { /* nao era lista serializada valida, usa o texto cru abaixo */ }
  }
  return trimmed;
}

let mensagemNova = '';
try {
  const merge = $('Merge1').first().json;
  if (merge && merge.message && merge.message !== 'unknown') mensagemNova = merge.message;
} catch (e) {}
if (!mensagemNova) {
  try {
    mensagemNova = limparBufferDebounce($('messageAgregated').first().json.messageUser);
  } catch (e) {}
}
if (!mensagemNova) mensagemNova = norm.message_object_textmessage || '';
if (!mensagemNova) mensagemNova = 'unknown';

const systemPrompt = (persona.system_prompt || '')
  .split('[[agente_nome]]').join(persona.agente_nome || '')
  .split('[[cliente_nome]]').join(cliente.nome || '')
  .split('[[link_calendly]]').join(persona.link_calendly || '')
  .split('[[perguntas]]').join(cliente.perguntas || '');

const prompt = systemPrompt + '\n\n'
  + '=== DADOS DO LEAD ===\n'
  + 'Nome: ' + (lead.Name || norm.user_name || 'desconhecido') + '\n'
  + 'Email: ' + (lead.Email || '(nao informado)') + '\n'
  + 'Telefone: ' + norm.user_phone + '\n\n'
  + '=== ESTADO DA REUNIAO ===\n'
  + estadoReuniao + '\n'
  + detalheReuniao + '\n\n'
  + '=== ESTADO DA CONVERSA ===\n'
  + estadoConversa + '\n\n'
  + '=== RESPOSTAS JA RECOLHIDAS ===\n'
  + respostasDadas + '\n\n'
  + '=== HISTORICO DA CONVERSA ===\n'
  + historico + '\n\n'
  + '=== MENSAGEM NOVA DO LEAD ===\n'
  + mensagemNova + '\n\n'
  + 'Responda agora, APENAS com o objeto JSON no formato obrigatorio.';

return [{
  json: {
    prompt: prompt,
    timeout: 120,
    user_phone: norm.user_phone,
    user_name: norm.user_name,
    message_nova: mensagemNova,
    airtable_record_id: lead['Airtable ID'] || lead.id || '',
    cliente_ativo: persona.cliente_ativo,
    email_atendimento: cliente.email
  }
}];

const bridgeOutput = $input.first().json;
const txt = bridgeOutput.output || '';

const loginFail = txt.includes('Not logged in') || txt.includes('Please run /login');
const tooShort = txt.trim().length <= 10;

if (txt && !loginFail && !tooShort) {
  return [{ json: {
    output: txt,
    elapsed_s: bridgeOutput.elapsed_s || 0,
    fallback: false,
    prompt: $('Build Prompt').first().json.prompt
  } }];
}

return [{ json: {
  output: '',
  elapsed_s: 0,
  fallback: true,
  prompt: $('Build Prompt').first().json.prompt
} }];

const raw = $('Fallback Router SDR').first().json.output || '';
const clean = raw.replace(/```json/g, '').replace(/```/g, '').trim();

let p;
try {
  p = JSON.parse(clean);
} catch (e) {
  p = { resposta: 'Desculpe, pode repetir por favor?', idioma: 'pt', acao: 'nenhuma', campo_resposta: null, valor_resposta: null, qualificacao_completa: false, _parse_failed: true };
}

const bp = $('Build Prompt').first().json;
return [{ json: {
  resposta: p.resposta || '',
  idioma: p.idioma || 'pt',
  acao: p.acao || 'nenhuma',
  campo_resposta: p.campo_resposta || null,
  valor_resposta: p.valor_resposta || null,
  qualificacao_completa: p.qualificacao_completa || false,
  user_phone: bp.user_phone,
  user_name: bp.user_name,
  message_nova: bp.message_nova,
  airtable_record_id: bp.airtable_record_id,
  cliente_ativo: bp.cliente_ativo,
  motor: 'bridge'
} }];

const j = $json;
const out = { airtable_record_id: j.airtable_record_id };
if (j.campo_resposta && j.valor_resposta) {
  out[j.campo_resposta] = j.valor_resposta;
}
return [{ json: out }];

const ctx = $('Set Contexto Resposta').first().json;
const merged = $input.first().json;
let resposta = ctx.resposta || '';
const link = merged.scheduling_link || '';
if (link && (ctx.acao === 'reagendar' || ctx.acao === 'agendar')) {
  resposta = (resposta ? resposta + '\n\n' : '') + 'Escolha o melhor horario aqui: ' + link;
}
let linkMeet = '';
try {
  const s = $('Airtable - Search User in Leads Autobot1').first().json;
  linkMeet = s.linkMeet || (s.fields && s.fields.linkMeet) || '';
} catch (e) {
  linkMeet = '';
}
// FIX 2026-07-15: 3 gatilhos - (1) transicao para qualificado (turno Q6 salvo), (2) lead pede link/reuniao/meet/horario/agenda, (3) reagendar (tratado acima). Evita spam do link em qualquer msg pos-qualificacao.
const msgNovaLower = String(ctx.message_nova || '').toLowerCase();
const leadPediuLink = /\blink\b/i.test(msgNovaLower);
const leadWantsChange = /(reagend|remarc|antecipar|adiar|cancel|desmarc|desistir)/i.test(msgNovaLower);
const transicaoQualificado = ctx.acao === 'salvar_resposta' && ctx.qualificacao_completa === true;
const acoesSemLembrete = ['cancelar', 'reagendar', 'agendar', 'atendimento_humano'];
if (linkMeet && !acoesSemLembrete.includes(ctx.acao) && !leadWantsChange && (transicaoQualificado || leadPediuLink)) {
  resposta = (resposta ? resposta + '\n\n' : '')
    + 'Como lembrete, a sua reuniao ja esta agendada. Aqui esta o link novamente: ' + linkMeet;
}
return [{ json: {
  resposta: resposta,
  user_phone: ctx.user_phone,
  user_name: ctx.user_name,
  message_nova: ctx.message_nova,
  airtable_record_id: ctx.airtable_record_id
} }];

// Função para dividir o texto em mensagens com base em duas quebras de linha consecutivas
function splitTextIntoMessages(text) {
    if (typeof text !== 'string') {
        console.log('Invalid input: text is not a string', text);
        throw new Error('Invalid input: text must be a string');
    }
    return text.split('\n\n').map(part => part.trim()).filter(part => part.length > 0).map(part => {
        return { json: { message: part } };
    });
}

// Log the input data for debugging
console.log('Input items:', JSON.stringify(items, null, 2));

// Check if msgs exists and is a string
const inputText = items[0]?.json?.msgs;

if (typeof inputText !== 'string') {
    console.log('Invalid input: items[0].json.msgs is not a valid string', inputText);
    throw new Error('Invalid input: items[0].json.msgs is not a valid string');
}

// Split the text into messages
const messages = splitTextIntoMessages(inputText);

// Return the messages as n8n items
return messages;

