// Custom UUID generation function
function uuidv4() {
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
        const r = Math.random() * 16 | 0,
              v = c === 'x' ? r : (r & 0x3 | 0x8);
        return v.toString(16);
    });
}

// Get all input data from n8n
const inputData = $input.all();
const outputData = [];

// Process each input item
for (let item of inputData) {
    // Ensure 'conversations' object exists
    let conversations = item.json?.conversations || {};

    // Extract phone number safely
    const phone = item.json?.Telefone || "Unknown";  // Airtable field "Telefone"

    // Extract the message content safely
    const messageText = item.json?.concat_Messages || "No message provided";  

    // Extract or generate a conversation ID
    let conversationId = uuidv4();

    // Ensure a conversation exists for this phone number
    if (!conversations[phone]) {
        conversations[phone] = { conversationId, conversation: [] };
    }

    // Create message object
    const message = {
        text: messageText,
        timestamp: new Date().toISOString()
    };

    // Append message to conversation
    conversations[phone].conversation.push(message);

    // Push structured output
    outputData.push({
        ...item.json,
        conversationId,
        conversation: conversations[phone].conversation
    });
}

// Return structured data
return outputData;

// Audio Base64 From Payload — Fixed for Evolution API v2
// Downloads audio via getBase64FromMediaMessage endpoint
// Falls back to direct base64 if available in webhook payload

const webhookBody = $('Webhook').item.json.body;

// 1. Try direct base64 (works if Evolution API has webhook_base64 enabled)
const directB64 = webhookBody?.data?.message?.base64;
if (directB64) {
  return [{ json: { base64: directB64 } }];
}

// 2. Download via Evolution API getBase64FromMediaMessage
const serverUrl = webhookBody?.server_url;
const instanceName = $('Evo Credentials').item.json.nome_da_instancia;
const apiKey = $('Evo Credentials').item.json.evo_api_key;
const messageKey = webhookBody?.data?.key;

if (!serverUrl || !instanceName || !apiKey || !messageKey) {
  throw new Error(
    'Audio download failed — missing: ' +
    [!serverUrl && 'serverUrl', !instanceName && 'instanceName',
     !apiKey && 'apiKey', !messageKey && 'messageKey'].filter(Boolean).join(', ')
  );
}

const resp = await fetch(
  `${serverUrl}/chat/getBase64FromMediaMessage/${instanceName}`,
  {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'apikey': apiKey },
    body: JSON.stringify({ message: { key: messageKey }, convertToMp4: false })
  }
);

if (!resp.ok) {
  const errText = await resp.text();
  throw new Error(`Evolution API ${resp.status}: ${errText.substring(0, 300)}`);
}

const result = await resp.json();
let base64 = result.base64 || '';

// Strip data URI prefix if present ("data:audio/ogg;base64,...")
if (base64.includes(',')) {
  base64 = base64.split(',')[1];
}

if (!base64) {
  throw new Error('Evolution API returned empty base64 for audio message');
}

return [{ json: { base64 } }];

// Image Base64 From Payload — Fixed for Evolution API v2
// Downloads image via getBase64FromMediaMessage endpoint

const webhookBody = $('Webhook').item.json.body;

// 1. Try direct base64
const directB64 = webhookBody?.data?.message?.base64;
if (directB64) {
  let media_type = 'image/jpeg';
  if (directB64.startsWith('iVBOR')) media_type = 'image/png';
  else if (directB64.startsWith('R0lGOD')) media_type = 'image/gif';
  else if (directB64.startsWith('UklGR')) media_type = 'image/webp';
  return [{ json: { base64: directB64, media_type } }];
}

// 2. Download via Evolution API getBase64FromMediaMessage
const serverUrl = webhookBody?.server_url;
const instanceName = $('Evo Credentials').item.json.nome_da_instancia;
const apiKey = $('Evo Credentials').item.json.evo_api_key;
const messageKey = webhookBody?.data?.key;

if (!serverUrl || !instanceName || !apiKey || !messageKey) {
  throw new Error(
    'Image download failed — missing: ' +
    [!serverUrl && 'serverUrl', !instanceName && 'instanceName',
     !apiKey && 'apiKey', !messageKey && 'messageKey'].filter(Boolean).join(', ')
  );
}

const resp = await fetch(
  `${serverUrl}/chat/getBase64FromMediaMessage/${instanceName}`,
  {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'apikey': apiKey },
    body: JSON.stringify({ message: { key: messageKey }, convertToMp4: false })
  }
);

if (!resp.ok) {
  const errText = await resp.text();
  throw new Error(`Evolution API ${resp.status}: ${errText.substring(0, 300)}`);
}

const result = await resp.json();
let base64 = result.base64 || '';
let media_type = 'image/jpeg';

// Strip data URI prefix and detect type
if (base64.includes(',')) {
  const prefix = base64.split(',')[0];
  if (prefix.includes('png')) media_type = 'image/png';
  else if (prefix.includes('gif')) media_type = 'image/gif';
  else if (prefix.includes('webp')) media_type = 'image/webp';
  base64 = base64.split(',')[1];
} else {
  if (base64.startsWith('iVBOR')) media_type = 'image/png';
  else if (base64.startsWith('R0lGOD')) media_type = 'image/gif';
  else if (base64.startsWith('UklGR')) media_type = 'image/webp';
}

if (!base64) {
  throw new Error('Evolution API returned empty base64 for image message');
}

return [{ json: { base64, media_type } }];

