// Anti-Loop Guard — detect bot-vs-bot loops
const search = $input.first().json;
const norm = $('Normalizacao').first().json;

const currentMsg = String(norm.message_object_textmessage || '').trim();
const concat = String(search.concat_Messages || '');
const alreadyOffBot = search.off_Bot === true;

// LAYER 1: Auto-reply pattern signatures
const autoReplyPatterns = [
  /^\s*prezad[oa]\(a\)/i,
  /agradec[eio]?\w*\s+(o\s+)?(seu|vosso|para o)?\s*(contato|contacto)/i,
  /out[- ]of[- ]office|fora do escrit[oó]rio|resposta autom[aá]tica|automatic reply|auto[- ]?reply/i,
  /this is an? automated (message|response|reply|email)/i,
  /pedimos a gentileza de descrever/i,
  /para que possamos melhor compreender/i,
  /obrigad[oa][,.]?\s+pelo\s+(seu|vosso)\s+(contato|contacto)/i,
  /thank you for (contacting|reaching out|your message)/i,
  /^\s*(bom dia|boa tarde|boa noite)[,.]?\s+(estamos|nao estamos|nao estou|de f[eé]rias)/i,
];
const looksAutoReply = currentMsg && autoReplyPatterns.some(re => re.test(currentMsg));

// LAYER 2: Exact duplicate against last 3 Lead messages
let isDuplicate = false;
if (concat && currentMsg && currentMsg.length > 15) {
  const blocks = concat.split(/\n\nData: /);
  const leadMsgs = blocks
    .filter(b => b.includes('Sender: Lead'))
    .map(b => {
      const idx = b.indexOf(' - Message: ');
      return idx > 0 ? b.substring(idx + 12).trim() : '';
    })
    .filter(Boolean);
  const recent3 = leadMsgs.slice(-3);
  isDuplicate = recent3.some(m => m === currentMsg);
}

// LAYER 3: Burst frequency (5+ msgs in 5 min)
let isBurst = false;
if (concat) {
  const now = Date.now();
  const timeRegex = /Data: (\d{4}-\d{2}-\d{2}) (\d{2}:\d{2})/g;
  const times = [];
  let m;
  while ((m = timeRegex.exec(concat)) !== null) {
    const iso = m[1] + 'T' + m[2] + ':00Z';
    const t = new Date(iso).getTime();
    if (!isNaN(t)) times.push(t);
  }
  const last5min = times.filter(t => (now - t) < 5 * 60 * 1000 && (now - t) > 0);
  isBurst = last5min.length >= 5;
}

const shouldBlock = looksAutoReply || isDuplicate || isBurst;
const blockReason = looksAutoReply ? 'auto-reply-pattern'
                  : isDuplicate ? 'duplicate-content'
                  : isBurst ? 'burst-frequency'
                  : null;

let action = 'continue';
if (shouldBlock) action = alreadyOffBot ? 'silent-skip' : 'mark-and-notify';

return [{
  json: {
    ...search,
    _guard: { shouldBlock, blockReason, alreadyOffBot, action, currentMsg: currentMsg.substring(0, 200) }
  }
}];
